/// Computes the greatest common divisor (GCD) of two positive integers
/// using the subtraction‐based Euclidean algorithm.  
/// Preconditions: `m > 0`, `n > 0`.  
/// All intermediate values remain positive, and the loop strictly
/// decreases the larger of the two at each step, guaranteeing termination.
pub fn gcd_i(mut m: i32, mut n: i32) -> i32 {
    // Optional runtime check for the precondition
    debug_assert!(m > 0 && n > 0, "gcd_i requires both inputs to be strictly positive");

    // Subtraction‐based Euclid's algorithm
    while m != n {
        if m > n {
            m -= n;
        } else {
            n -= m;
        }
    }
    // When they are equal, that's the GCD
    m
}

